// Original Root-reviewed empty-PG serializers, generated by MockTransport.
// They prove structural/byte-capacity parity, NOT real 32768-token feasibility
// or report quality. Component tests execute actual JSX/hooks with GET doubles;
// they are not a browser, authentication or physical-restart acceptance claim.
import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile,mkdtemp,writeFile,rm} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {tmpdir} from 'node:os';
import {resolve,join} from 'node:path';
import {pathToFileURL} from 'node:url';
import {build} from 'vite';
import {mount} from '../scripts/react-event-harness.mjs';
import {memory,tabFor,missing,reseal,nodes,text} from './report-evidence-v4-fixture.mjs';
import {copy,verifyEvidencePreview,verifyEvidenceDraft,verifyEvidenceReductionPreview,
 evidenceReviewValue} from '../src/report-evidence-reading-contract.mjs';
import {evidenceV5ManualAvailability} from '../src/report-evidence-v5-contract.mjs';
import {evidenceManualFromProjectionV6} from '../src/report-evidence-manual-v6-adapter.mjs';

const previousSession=globalThis.sessionStorage;
globalThis.sessionStorage??=tabFor();
const {ReportEvidenceReadingSession}=await import('../src/report-evidence-reading-session.mjs');
const directory=new URL('./fixtures/report-evidence-v5-large/',import.meta.url);
const base='/setup/report-evidence-readings',humanLimit=512*1024;
const files=['large-reduce-preview','large-reduce-start','large-reduced','large-semantic','mapped','preview','start'];
const size=value=>new TextEncoder().encode(JSON.stringify(value)).byteLength;
let Panel,Editor,temporary;

async function fixture(){
 const manifest=JSON.parse(await readFile(new URL('manifest.json',directory),'utf8'));
 assert.equal(manifest.schema,'report-evidence-public-synthetic-large-serializer-fixture-v1');
 assert.equal(manifest.scope,'MockTransport only; validates structural capacity, not real 32768-token feasibility or quality');
 assert.deepEqual(manifest.files.map(pin=>pin.file),files.map(name=>name+'.json'));
 const f={};
 for(const pin of manifest.files){
  const bytes=await readFile(new URL(pin.file,directory));
  assert.deepEqual(Object.keys(pin).sort(),['bytes','file','sha256']);
  assert.equal(bytes.byteLength,pin.bytes,pin.file);
  assert.equal(createHash('sha256').update(bytes).digest('hex'),pin.sha256,pin.file);
  f[pin.file.slice(0,-5)]=JSON.parse(bytes);
 }
 f.account={user_id:f.preview.actor_id,workspace_id:f.preview.workspace_id,role:'admin'};
 return f;
}

test.before(async()=>{
 temporary=await mkdtemp(join(tmpdir(),'evidence-v5-large-'));
 const built=await build({configFile:false,envDir:temporary,logLevel:'silent',cacheDir:join(temporary,'cache'),
  build:{ssr:resolve('src/ReportEvidenceReadingDialog.jsx'),write:false,minify:false,
   rollupOptions:{output:{format:'es',inlineDynamicImports:true,
    paths:id=>id==='react'?pathToFileURL(resolve('node_modules/react/index.js')).href:id}}}});
 const path=join(temporary,'dialog.mjs');await writeFile(path,built.output.find(output=>output.isEntry).code);
 const module=await import(pathToFileURL(path));Panel=module.ReportEvidenceReadingPanel;Editor=module.EvidenceCandidateEditor;
});
test.after(async()=>{
 if(temporary)await rm(temporary,{recursive:true,force:true});
 if(previousSession===undefined)delete globalThis.sessionStorage;else globalThis.sessionStorage=previousSession;
});

test('real dynamic-32768 serializers cold-verify the complete large model and independent Map/Reduce proofs',async()=>{
 const f=await fixture(),before=copy(f),row=f['large-semantic'];
 await verifyEvidencePreview(f.preview,f.account);
 await verifyEvidenceDraft(f.start.draft,f.account);await verifyEvidenceDraft(f.mapped,f.account);
 await verifyEvidenceReductionPreview(f['large-reduce-preview'],f.account,f.mapped);
 await verifyEvidenceDraft(f['large-reduce-start'].draft,f.account);
 await verifyEvidenceDraft(row,f.account);
 assert.deepEqual(row,f['large-reduced']);assert.equal(row.schema,'report-evidence-reading-draft-v3');
 const policy=f['large-reduce-preview'].reduction_preparation.generation_contract;
 assert.equal(policy.dispatch_options.max_tokens,32768);assert.equal(policy.input_policy.max_output_tokens,32768);
 assert.equal(row.preview.preparation_cap.execution.report_evidence_output.max_tokens,32768);
 assert.ok(row.maps.every(stage=>stage.receipt.evidence_profile.max_output_tokens===8192));
 assert.equal(row.reduction.receipt.evidence_profile.max_output_tokens,32768);
 assert.equal(row.reduction.journal.schema,'report-evidence-journal-descriptor-v2');
 assert.equal(row.reduction.start_receipt.schema,'report-evidence-reduce-receipt-v3');
 assert.equal(row.model_result.schema,'report-evidence-candidate-projection-v6');
 assert.ok(size(row.model_result)>humanLimit&&size(row.model_result)<1024*1024);
 assert.equal(row.model_result.global_claims.length,row.maps.length+96);
 assert.equal(Array.from(row.model_result.global_claims.at(-1).statement).length,1900);
 assert.ok(row.model_result.global_claims.slice(-96).every(claim=>claim.status==='unknown'
  &&claim.span_refs.length===0&&claim.explanation.trim()));
 assert.equal(row.review_value,null);assert.deepEqual(row.review_history,[]);
 assert.deepEqual(f,before);
});

test('session loads the complete original large model with no manual value, nonce, save or provider request',async()=>{
 const f=await fixture(),row=f['large-semantic'],before=copy(row),storage=memory(),calls=[];
 const session=new ReportEvidenceReadingSession({account:f.account,
  materialID:f.preview.body.selection.original_ref.id,storage,tabStorage:tabFor(f.account),
  locks:{request:async(_key,_options,fn)=>fn()},request:async(path,options={})=>{
   calls.push({path,...options});assert.ok(options.method===undefined||options.method==='GET');
   if(path==='/me')return copy(f.account);if(path===base+'/'+row.id)return copy(row);throw missing();
  }});
 try{
  await session.load(row.id);assert.deepEqual(session.row.model_result,row.model_result);
  assert.equal(session.state.draft_id,row.id);assert.equal(session.state.revision,row.revision);
  assert.equal(session.state.value,null);assert.equal(session.localSaved,true);assert.equal(session.state.pending,null);
  const available=evidenceV5ManualAvailability(session.row);
  assert.equal(available.allowed,false);assert.match(available.reason,/512 KiB/);
  assert.match(available.reason,/未截断、采用或生成一份缩短人工稿/);
  assert.equal(evidenceReviewValue(session.row),null);
  assert.throws(()=>evidenceManualFromProjectionV6(row.model_result),/512 KiB/);
  const state=copy(session.state),requestCount=calls.length;
  await assert.rejects(session.save(),/尚无汇总候选可保存/);
  assert.deepEqual(session.state,state);assert.equal(calls.length,requestCount);
  assert.deepEqual(calls.map(call=>call.path),['/me',base+'/'+row.id]);
  assert.equal(calls.some(call=>call.method==='PUT'||call.method==='POST'),false);
  assert.deepEqual(row,before);
 }finally{session.dispose();}
});

async function ready(ui,id){
 const deadline=Date.now()+15000;
 while(Date.now()<deadline){
  await ui.flush();const tree=ui.render(),alerts=nodes(tree).filter(node=>node.props.role==='alert').map(text);
  if(alerts.length)assert.fail('Actual large-candidate panel: '+alerts.join(' | '));
  if(nodes(tree).some(node=>node.props['data-evidence-draft-id']===id)
    &&!text(tree).includes('正在核对来源或保存记录'))return tree;
  await new Promise(resolve=>setTimeout(resolve,10));
 }
 assert.fail('Actual large-candidate panel did not finish its observable GET hydration');
}

test('actual Dialog renders the last full 1900-character declaration and business semantics only as readonly',async()=>{
 const f=await fixture(),row=f['large-semantic'],before=copy(row),calls=[],storage=memory(),tab=tabFor(f.account);
 const previous={window:globalThis.window,localStorage:globalThis.localStorage,sessionStorage:globalThis.sessionStorage};
 globalThis.window={addEventListener(){},removeEventListener(){}};globalThis.localStorage=storage;globalThis.sessionStorage=tab;
 const list=await reseal({schema:'report-evidence-reading-list-v1',actor_id:f.account.user_id,
  workspace_id:f.account.workspace_id,items:[]},'list_hash');
 const props={account:f.account,material:{...f.preview.body.selection.original_ref,name:'合成容量核对报告.docx'},
  initialDraftID:row.id,Dialog:({children})=>children,Btn:({children})=>children,storage,tabStorage:tab,
  locks:{request:async(_key,_options,fn)=>fn()},onClose(){},
  prepareDraft:async()=>assert.fail('Opening the readonly model must not save setup configuration'),
  request:async(path,options={})=>{
   calls.push({path,...options});assert.ok(options.method===undefined||options.method==='GET','No write/model request');
   if(path==='/me')return copy(f.account);
   if(path==='/setup/understanding/models')return [{id:f.preview.body.model_id,name:'合成已发布模型',model:f.preview.model}];
   if(path===base)return list;if(path===base+'/'+row.id)return copy(row);throw missing();
  }};
 let ui,editor;
 try{
  ui=mount(Panel,props);const tree=await ready(ui,row.id),all=nodes(tree),content=text(tree);
  assert.match(content,/超过当前512 KiB人工稿保存上限/);
  assert.match(content,/未截断、采用或生成一份缩短人工稿/);
  assert.ok(all.some(node=>node.type==='summary'&&text(node)==='查看不可变的原汇总候选（与人工稿分开）'));
  const candidates=all.filter(node=>node.type===Editor);assert.equal(candidates.length,1);
  assert.equal(candidates[0].props.writable,false);assert.deepEqual(candidates[0].props.value.result,row.model_result);
  assert.equal(all.some(node=>text(node)==='保存完整人工稿并核对服务器回执'),false);
  editor=mount(Editor,candidates[0].props);const last=row.model_result.global_claims.length-1;
  const statement=editor.byAria('result.global_claims.'+last+'.statement');
  assert.equal(statement.props.value,row.model_result.global_claims[last].statement);
  assert.equal(Array.from(statement.props.value).length,1900);assert.equal(statement.props.readOnly,true);
  assert.equal(editor.byAria('result.global_claims.'+last+'.status').props.value,'unknown');
  assert.equal(editor.byAria('result.global_claims.'+last+'.status').props.disabled,true);
  const b=row.model_result.businesses[0];
  for(const [path,expected] of [
   ['result.businesses.0.steps.0.purpose',b.steps[0].purpose],['result.businesses.0.steps.0.role',b.steps[0].role],
   ['result.businesses.0.participants.0.responsibility',b.participants[0].responsibility],
   ['result.businesses.0.interactions.0.condition',b.interactions[0].condition],
   ['result.businesses.0.conditions.0.statement',b.conditions[0].statement],
   ['result.businesses.0.coordination.0.start_rule',b.coordination[0].start_rule],
  ]){const control=editor.byAria(path);assert.equal(control.props.value,expected);assert.equal(control.props.readOnly,true);}
  assert.ok(nodes(editor.render()).filter(node=>node.type==='textarea').every(node=>node.props.readOnly===true));
  assert.ok(nodes(editor.render()).filter(node=>node.type==='select').every(node=>node.props.disabled===true));
  assert.equal(editor.button('保留一个待核问题').props.disabled,true);
  assert.equal(calls.some(call=>call.method==='PUT'||call.method==='POST'),false);assert.deepEqual(row,before);
 }finally{editor?.unmount();ui?.unmount();Object.assign(globalThis,previous);}
});
